def remove_duplicate_letters_keep_first(s):
    seen = set()
    out = []
    for ch in s:
        if ch not in seen:
            seen.add(ch)
            out.append(ch)
    return ''.join(out)

def is_pangram(s):
    import string
    letters = set(ch for ch in s.lower() if ch.isalpha())
    return set(string.ascii_lowercase).issubset(letters)

def group_anagrams(words):
    groups = {}
    order = []
    for w in words:
        key = ''.join(sorted(w))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(w)
    return [groups[k] for k in order]

def char_frequency(s):
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    return freq

def most_frequent_char(s):
    if not s:
        return ""
    freq = {}
    order = []
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
            order.append(ch)
        freq[ch] += 1
    best = order[0]
    for ch in order[1:]:
        if freq[ch] > freq[best]:
            best = ch
    return best

