def longest_substring_without_repeat(s):
    best = ""
    start = 0
    seen = {}
    for i, ch in enumerate(s):
        if ch in seen and seen[ch] >= start:
            start = seen[ch] + 1
        seen[ch] = i
        if i - start + 1 > len(best):
            best = s[start:i+1]
    return best

def can_form_palindrome(s):
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    odd = sum(1 for c in freq.values() if c % 2 == 1)
    return odd <= 1

def longest_palindromic_substring(s):
    if not s:
        return ""
    best = s[0]
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return s[l+1:r]
    for i in range(len(s)):
        odd = expand(i, i)
        if len(odd) > len(best):
            best = odd
        even = expand(i, i+1)
        if len(even) > len(best):
            best = even
    return best

def count_palindromic_substrings(s):
    n = len(s)
    count = 0
    def expand(l, r):
        nonlocal count
        while l >= 0 and r < n and s[l] == s[r]:
            count += 1
            l -= 1
            r += 1
    for i in range(n):
        expand(i, i)
        expand(i, i+1)
    return count

def is_rotation(s1, s2):
    if len(s1) != len(s2):
        return False
    if len(s1) == 0:
        return True
    return s2 in (s1 + s1)

def remove_punctuation(s):
    import string
    return ''.join(ch for ch in s if ch not in string.punctuation)

def alternate_case(s):
    out = []
    idx = 0
    for ch in s:
        if ch.isalpha():
            out.append(ch.upper() if idx % 2 == 0 else ch.lower())
            idx += 1
        else:
            out.append(ch)
    return ''.join(out)

def snake_to_camel(s):
    parts = s.split('_')
    if not parts:
        return s
    result = parts[0]
    for p in parts[1:]:
        if p:
            result += p[0].upper() + p[1:]
    return result

def camel_to_snake(s):
    out = []
    for i, ch in enumerate(s):
        if ch.isupper():
            if i > 0:
                out.append('_')
            out.append(ch.lower())
        else:
            out.append(ch)
    return ''.join(out)

def is_all_digits(s):
    if not s:
        return False
    return all(ch.isdigit() for ch in s) and all(ch in "0123456789" for ch in s)

def first_non_repeating_char(s):
    for ch in s:
        if s.count(ch) == 1:
            return ch
    return None
